// IndexedDB for recordings
function idb(cb){ try{ var r = indexedDB.open("ihsan_grow", 1); r.onupgradeneeded = function(){ r.result.createObjectStore("rec"); }; r.onsuccess = function(){ cb(r.result); }; r.onerror = function(){ cb(null); }; }catch(e){ cb(null); } }
